// ============================================================
// 5개 Scene MP4 Binary Data 및 메타데이터 변환 로직
// ============================================================

const items = $input.all();

if (!items || items.length === 0) {
  throw new Error("전달받은 MP4 데이터가 없습니다.");
}

return items.map((item, index) => {
  const binary = item.binary?.data;
  const json = item.json || {};

  if (!binary) {
    throw new Error(`[Scene ${json.scene || index + 1}] MP4 binary data가 없습니다.`);
  }

  const filename = json.filename || binary.fileName;
  const url = `http://host.docker.internal:8188/view?filename=${filename}&type=${json.type || 'output'}`;

  return {
    json: {
      status: "success",
      scene: json.scene || (index + 1),
      prompt_id: json.prompt_id || "",
      filename: filename,
      url: url,
      extension: binary.fileExtension || "mp4",
      mime_type: binary.mimeType || "video/mp4",
      file_size: binary.fileSize,
      directory: binary.directory || "/files"
    },
    binary: {
      data: binary
    }
  };
});

// ============================================================
// ComfyUI History 검사 및 5개 Scene MP4 전체 추적/선별 로직
// ============================================================

let promptSceneMap = new Map();
let targetPromptIds = [];

try {
  const req2Items = $("HTTP Request2").all();
  req2Items.forEach((item, index) => {
    const pId = item.json.prompt_id;
    const sceneNum = item.json.scene || (index + 1);
    if (pId) {
      promptSceneMap.set(pId, { scene: sceneNum, prompt_id: pId, order: index + 1 });
      targetPromptIds.push(pId);
    }
  });
} catch (e) {
  targetPromptIds = [];
}

const expectedTotalCount = targetPromptIds.length > 0 ? targetPromptIds.length : 5;
let rawItems = $input.all();
if (!rawItems || rawItems.length === 0 || !rawItems[0].json || Object.keys(rawItems[0].json).length === 0) {
  rawItems = $("HTTP Request3").all();
}

const videoMap = new Map();
for (const item of rawItems) {
  const result = item.json;
  if (!result || typeof result !== "object") continue;
  for (const [promptId, history] of Object.entries(result)) {
    if (!history || typeof history !== "object") continue;
    if (targetPromptIds.length > 0 && !targetPromptIds.includes(promptId)) continue;
    const outputs = history.outputs;
    if (!outputs || typeof outputs !== "object") continue;
    for (const [nodeId, nodeOutput] of Object.entries(outputs)) {
      const mediaList = nodeOutput.gifs || nodeOutput.images || [];
      if (!Array.isArray(mediaList) || mediaList.length === 0) continue;
      for (const media of mediaList) {
        if (!media?.filename) continue;
        const filename = media.filename;
        if (!/\.(mp4|gif|webp)$/i.test(filename)) continue;
        const sceneInfo = promptSceneMap.get(promptId) || { scene: 0, order: 0 };
        videoMap.set(promptId, { ready: true, scene: sceneInfo.scene, order: sceneInfo.order, prompt_id: promptId, media_type: "video", node_id: nodeId, filename, subfolder: media.subfolder || "", type: media.type || "output", format: media.format || "", frame_rate: media.frame_rate || null, fullpath: media.fullpath || "" });
      }
    }
  }
}

const completedVideoCount = videoMap.size;
const staticData = $getWorkflowStaticData('global');
staticData.retryCount = (staticData.retryCount || 0) + 1;
const MAX_RETRIES = 60;

if (staticData.retryCount > MAX_RETRIES) {
  staticData.retryCount = 0;
  throw new Error(`[ComfyUI 타임아웃] 최대 대기 시간을 초과했습니다. (완료: ${completedVideoCount}/${expectedTotalCount})`);
}

if (completedVideoCount < expectedTotalCount) {
  return [{ json: { ready: false, media_type: "video", expected_video_count: expectedTotalCount, completed_video_count: completedVideoCount, retry_count: staticData.retryCount, status: `Generating... (${completedVideoCount}/${expectedTotalCount} done)` } }];
}

staticData.retryCount = 0;
const sortedVideos = Array.from(videoMap.values()).sort((a, b) => a.order - b.order);
return sortedVideos.map(video => ({ json: { ready: true, scene: video.scene, prompt_id: video.prompt_id, media_type: "video", node_id: video.node_id, filename: video.filename, subfolder: video.subfolder, type: video.type, format: video.format, frame_rate: video.frame_rate, fullpath: video.fullpath, status: `Scene ${video.scene} Video Ready` } }));

